// VehiclesSection.tsx
// Sección principal de vehículos de la landing page de Ferradas Automotores.
// Permite buscar y filtrar vehículos por marca, modelo y condición (nuevo/usado).
// Muestra un grid/carrusel de vehículos usando VehicleGrid y maneja el estado de búsqueda y filtro.
// Incluye función de formateo de precio (actualmente no usada en el render).

import React, { useState, useEffect, useMemo } from "react";
import { Link } from "react-router-dom";
import VehicleGrid from "./VehicleGrid";
import SearchAndFilter from "./SearchAndFilter";
import { useVehicles } from "../hooks/useVehicles";
import { ChevronRight, ArrowRight, LayoutGrid, GitCompare } from "lucide-react";

const VehiclesSection: React.FC = () => {
  const { vehicles: allVehicles, loading } = useVehicles();

  // Leer estado inicial de localStorage
  const [filterCondition, setFilterCondition] = useState<"all" | "new" | "used">(() => {
    return (localStorage.getItem("filterCondition") as "all" | "new" | "used") || "all";
  });
  const [searchTerm, setSearchTerm] = useState(() => {
    return localStorage.getItem("searchTerm") || "";
  });

  // Guardar en localStorage cuando cambian
  useEffect(() => {
    localStorage.setItem("filterCondition", filterCondition);
  }, [filterCondition]);
  useEffect(() => {
    localStorage.setItem("searchTerm", searchTerm);
  }, [searchTerm]);

  // Acciones auxiliares
  const clearFilters = () => {
    setFilterCondition("all");
    setSearchTerm("");
    try {
      localStorage.removeItem("filterCondition");
      localStorage.removeItem("searchTerm");
    } catch {}
  };

  const filteredVehicles = useMemo(() => {
    if (!allVehicles) return [];
    
    // Ordenar para que Mustang y Raptor estén primero en el grid
    const orderedVehicles = [
      allVehicles.find(v => v.model.toLowerCase().includes("mustang")),
      allVehicles.find(v => v.model.toLowerCase().includes("raptor")),
      ...allVehicles.filter(v =>
        !v.model.toLowerCase().includes("mustang") &&
        !v.model.toLowerCase().includes("raptor")
      )
    ].filter(Boolean) as any[];

    // Filtrar para que el Onix no se muestre
    const visibleVehicles = orderedVehicles.filter(
      (vehicle) => !vehicle.model.toLowerCase().includes("onix")
    );

    // Filtrado de vehículos según búsqueda y condición
    return visibleVehicles.filter((vehicle) => {
      const matchesCondition =
        filterCondition === "all" || vehicle.condition === filterCondition;
      const matchesSearch =
        vehicle.brand.toLowerCase().includes(searchTerm.toLowerCase()) ||
        vehicle.model.toLowerCase().includes(searchTerm.toLowerCase());
      return matchesCondition && matchesSearch;
    });
  }, [allVehicles, filterCondition, searchTerm]);

  return (
    <section id="VehiclesSection" className="bg-vehicles-section py-16 md:py-20">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        {/* Header de sección */}
        <div className="text-center mb-8 md:mb-10 animate-fade-in-up">
          <p className="text-red-600 font-semibold text-xs sm:text-sm uppercase tracking-widest mb-2 sm:mb-3">
            Inventario
          </p>
          <h2 className="text-3xl sm:text-4xl md:text-5xl font-extrabold text-gray-900 tracking-tight">
            Nuestros{" "}
            <span className="bg-gradient-to-r from-red-600 to-red-500 bg-clip-text text-transparent">
              Vehículos
            </span>
          </h2>
          <p className="mt-3 sm:mt-4 text-gray-500 max-w-xl mx-auto text-sm sm:text-base md:text-lg px-4">
            Explorá nuestra selección de vehículos 0km y usados con la mejor financiación.
          </p>
        </div>

        {/* Search and Filter */}
        <SearchAndFilter
          searchTerm={searchTerm}
          setSearchTerm={setSearchTerm}
          filterCondition={filterCondition}
          setFilterCondition={setFilterCondition}
        />

        {/* Barra de acciones */}
        <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3 mb-4">
          <p className="text-sm text-gray-500">
            Mostrando{" "}
            <span className="font-bold text-gray-900">{filteredVehicles.length}</span>{" "}
            vehículos
          </p>
          <div className="flex flex-wrap gap-2 sm:ml-auto">
            {(searchTerm || filterCondition !== "all") && (
              <button
                onClick={clearFilters}
                className="inline-flex items-center gap-1.5 px-4 py-2 rounded-xl border border-gray-200 text-gray-600 hover:bg-white hover:border-gray-300 hover:text-gray-800 text-sm transition-all duration-200"
              >
                <svg className="w-3.5 h-3.5" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
                  <path strokeLinecap="round" strokeLinejoin="round" d="M6 18L18 6M6 6l12 12" />
                </svg>
                Limpiar filtros
              </button>
            )}
            <Link
              to="/comparar"
              className="inline-flex items-center gap-1.5 px-4 py-2 rounded-xl bg-gray-900 text-white shadow-sm hover:bg-red-600 transition-all duration-300 text-sm font-medium"
            >
              <GitCompare className="w-4 h-4" />
              Comparar
            </Link>
            <Link
              to="/consultar"
              className="inline-flex items-center gap-1.5 px-4 py-2 rounded-xl bg-green-600 text-white shadow-sm hover:bg-green-700 transition-all duration-200 text-sm font-medium"
            >
              Consultar
            </Link>
          </div>
        </div>

        {/* Vehicle Grid / Carousel */}
        <VehicleGrid vehicles={filteredVehicles} />

        {/* Link a ver todos */}
        <div className="text-center mt-8">
          <Link
            to="/vehiculos"
            className="inline-flex items-center gap-2 px-6 py-3 rounded-xl bg-white border border-gray-200 text-gray-800 font-semibold text-sm hover:border-red-300 hover:text-red-600 hover:shadow-md transition-all duration-300 group"
          >
            <LayoutGrid className="w-4 h-4" />
            Ver todos los vehículos
            <ArrowRight className="w-4 h-4 transition-transform duration-300 group-hover:translate-x-1" />
          </Link>
        </div>
      </div>
    </section>
  );
};

export default VehiclesSection;